"use strict";

// Generated by the build: only public static app resources belong in this list.
importScripts("./precache-manifest.js");
const BASE = self.registration.scope;
const SCOPE = new URL(BASE);
const CACHE_PREFIX = `fixmycity2-shell-${encodeURIComponent(SCOPE.pathname)}-`;
const CACHE_NAME = CACHE_PREFIX + self.FMC_PRECACHE.version;
const CLEAN_PAGES = new Map([["index.html", ""], ["welcome.html", "welcome"], ["scan-card.html", "scan-card"], ["scan-face.html", "scan-face"], ["home.html", "home"], ["privacy.html", "privacy"]]);
function staticURL(path) {
  if (typeof path !== "string" || path.startsWith("/") || path.includes("..")) {
    throw new Error("Invalid relative precache path");
  }
  const url = new URL(CLEAN_PAGES.has(path) ? CLEAN_PAGES.get(path) : path, BASE);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname) || url.search || url.hash) {
    throw new Error("Precache entry is outside this app");
  }
  return url.href;
}
const STATIC_URLS = new Set(self.FMC_PRECACHE.files.map(staticURL));
// Only the small public entry shell is installed up front. Large models and
// artwork for other screens are cached when those screens actually request them.
const SHELL = (self.FMC_PRECACHE.precache || self.FMC_PRECACHE.files).map((path) => {
  const url = staticURL(path);
  if (!STATIC_URLS.has(url)) throw new Error('Precache asset is not in the static allowlist');
  return url;
});
const LEGACY_PAGES = new Map([...CLEAN_PAGES].map(([file, clean]) => [new URL(file, BASE).pathname, new URL(clean, BASE).pathname]));

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(SHELL.map((url) => new Request(url, { cache: "default" })));
  })());
  // A new release waits until old app windows close; do not interrupt a scan or draft.
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

async function networkFirst(request, cacheKey) {
  const cache = await caches.open(CACHE_NAME);
  try {
    const response = await fetch(request);
    if (response.ok && response.type === "basic" && !response.redirected && !/no-store/i.test(response.headers.get("Cache-Control") || "")) {
      try { await cache.put(cacheKey, response.clone()); } catch { /* Storage limits do not prevent online use. */ }
    }
    if (response.status >= 500) {
      const saved = await cache.match(cacheKey);
      if (saved) return saved;
    }
    // Real 404s remain 404s. Never replace a missing script or image with HTML.
    return response;
  } catch (error) {
    const saved = await cache.match(cacheKey);
    if (saved) return saved;
    throw error;
  }
}

async function artworkFirst(request, cacheKey) {
  const cache = await caches.open(CACHE_NAME);
  const saved = await cache.match(cacheKey);
  return saved || networkFirst(request, cacheKey);
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const normalized = url.origin + url.pathname;
  if (request.mode === "navigate" && LEGACY_PAGES.has(url.pathname)) {
    url.pathname = LEGACY_PAGES.get(url.pathname);
    event.respondWith(Promise.resolve(Response.redirect(url.href, 308)));
  } else if (STATIC_URLS.has(normalized)) {
    const immutableArtwork = /\/assets\/onboarding\/[a-z-]+-[a-f0-9]{16}\.webp$/.test(url.pathname);
    event.respondWith(immutableArtwork ? artworkFirst(request, normalized) : networkFirst(request, normalized));
  }
  // Identity images, microphone recordings, APIs, and unrelated URLs are not cached.
});
